-- G3588 senses
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(72913, 'spa', 'artículo definido', 'El artículo definido básico que marca un sustantivo como conocido, específico, o mencionado previamente. Con más de 18,000 ocurrencias, es el uso fundamental en el Nuevo Testamento. Corresponde directamente a el/la/los/las en español, incluyendo formas contraídas como al (a + el) y del (de + el).');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(72932, 'spa', 'artículo conectivo o estructural', 'Enlaza cláusulas, marca transiciones, u organiza listas. Más visible en la genealogía de Mateo 1, donde el artículo repetido estructura la secuencia de nombres. A menudo se traduce de manera implícita en español o mediante conectores sutiles.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(72952, 'spa', 'sustantivizador o pronombre', 'Convierte adjetivos, participios, o frases preposicionales en frases sustantivas: «el que», «los que», «las cosas de». Esta función permite al griego crear expresiones nominales complejas sin sustantivo explícito. En español se traduce naturalmente con el artículo seguido del adjetivo o participio sustantivado.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(72935, 'spa', 'artículo dativo (objeto indirecto/locativo)', 'Marca objetos indirectos, ubicaciones, o instrumentos. El caso dativo griego comunica destinatario, lugar, o medio. En español se traduce típicamente con preposiciones: «al» (a + el), «en el», «con el», «del» (de + el cuando expresa procedencia).');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(72939, 'spa', 'artículo genitivo (posesivo/partitivo)', 'Marca posesión, fuente, o relaciones partitivas. El genitivo griego expresa pertenencia, origen, o parte de un todo. En español se traduce principalmente con «de» + artículo («del», «de la», «de los», «de las»), preservando la relación genitiva.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(72971, 'spa', 'artículo comparativo', 'Artículo en construcciones comparativas que siguen adjetivos comparativos. Solo 14 ocurrencias en el Nuevo Testamento. Se traduce en español como «que el/la/los/las» o «de lo que», dependiendo del contexto.');

-- H0853 senses
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(84875, 'spa', 'marcador de objeto directo definido', 'El marcador de objeto directo definido, antepuesto a sustantivos determinados (por artículo, constructo, nombre propio o sufijo). Intraducible en la mayoría de idiomas meta — inglés, francés y alemán lo dejan sin marcar, mientras que el español a veces usa la preposición acusativa «a». Su altísima frecuencia (10,915x) refleja cuán omnipresentes son las construcciones verbales transitivas en la narrativa y legislación del hebreo bíblico.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(84897, 'spa', 'con, junto a (preposición)', 'Preposición que significa «con, junto a, en compañía de», homográfica pero funcionalmente distinta del marcador de objeto. Se encuentra 62 veces en contextos de acompañamiento o proximidad, como en Núm 5:19 y Sal 31:7.');

-- G2532 senses
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(69825, 'spa', 'conjunción copulativa «y»', 'La conjunción copulativa «y», que une palabras, frases y cláusulas en secuencia. Conectivo por defecto de la prosa griega. Cada idioma lo traduce con su conjunción básica: español «y», francés «et». Más de 8,300 de las 9,083 apariciones.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(69826, 'spa', 'uso adverbial «también»', 'El uso adverbial o ascensivo que significa «también, aun, igualmente», añadiendo énfasis o un elemento inesperado. El español lo traduce distintivamente como «también». Se encuentra en Mat 5:39-40, Mat 5:46. Aproximadamente 771 apariciones.');

-- H3068 senses
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(101337, 'spa', 'YHWH (el nombre divino)', 'El nombre personal divino Yahvé, revelado en la zarza ardiente (Éxodo 3:14-15) y usado en toda la Escritura como el nombre pactal que vincula a Dios con Israel. Las traducciones multilingües reflejan la antigua tradición de sustitución: el español Yahvé mantiene la forma fonética, el francés l''Éternel enfatiza la eternidad, y el alemán HERR sigue la tradición de Adonai. 6,522 apariciones.');

-- H5921a senses
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(146277, 'spa', 'sobre, en (contacto físico)', 'Sentido espacial central: literalmente «encima de» o «sobre». 5,443 de 5,769 ocurrencias. Ejemplos: «Abraham se postró sobre su rostro» (Gén 17:17). Expresa contacto directo con una superficie.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(146278, 'spa', 'sobre, por encima de (superioridad)', 'Sentido adversativo o de dominio aunque etiquetado como «sobre». 120 ocurrencias. Indica superioridad vertical, autoridad o dominio sobre algo o alguien.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123903, 'spa', 'contra (adversativo)', 'Oposición o enemistad: «contra». Génesis 50:20 «vosotros pensasteis mal contra mí». Expresa hostilidad, confrontación u oposición directa.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123924, 'spa', 'junto a, al lado de (proximidad)', 'Cercanía sin contacto de superficie. 55 ocurrencias. Gén 24:13 «de pie junto al manantial». Indica proximidad espacial o presencia cercana sin implicar contacto físico.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123923, 'spa', 'a causa de, por lo tanto (causal)', 'Razón o fundamento. 51 ocurrencias. Génesis 20:6 «por eso te detuve de pecar». Introduce la causa, motivo o razón de una acción o situación.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123941, 'spa', 'acerca de, concerniente a (tópico)', 'Asunto o tema del habla o pensamiento. 39 ocurrencias. Gén 21:25 «acerca del pozo». Introduce el tema o materia sobre la cual se habla o piensa.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123945, 'spa', 'por, en favor de (benefactivo)', 'Beneficio derivado de una acción. 22 ocurrencias. Lev 16:30 «hacer expiación por vosotros». Indica que la acción beneficia o favorece a alguien.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123963, 'spa', 'hacia, a (direccional)', 'Movimiento hacia una meta. 19 ocurrencias. Éxo 3:18 «vayamos... al SEÑOR». Expresa dirección o destino del movimiento.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123947, 'spa', 'según, además de (normativo)', 'Sentido de norma o estándar y aditivo. 13 ocurrencias. Éxo 6:26 «según sus ejércitos». Indica conformidad con un patrón o adición a algo existente.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123960, 'spa', '(contexto incierto)', 'Siete ocurrencias de contexto incierto o dependiente. Uso especializado que requiere análisis contextual específico para determinar el sentido preciso.');

INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES
(123883, 'spa', 'sobre, en, encima de (espacial)', 'Sentido espacial central (grupo duplicado o dividido). Expresa la misma relación de superficie que el sentido 1, posiblemente una distinción contextual sutil.');
